import { Component, JSX, splitProps } from 'solid-js';

export interface CssMasonryProps extends JSX.HTMLAttributes<HTMLDivElement> {
  columns?: number;
  columnsSm?: number;
  columnsMd?: number;
  columnsLg?: number;
  columnsXl?: number;
  gap?: number;
  columnFill?: 'balance' | 'auto';
  height?: number;
}

export const CssMasonry: Component<CssMasonryProps> = (props) => {
  const [local, others] = splitProps(props, [
    'columns',
    'columnsSm',
    'columnsMd',
    'columnsLg',
    'columnsXl',
    'gap',
    'columnFill',
    'height',
    'class',
    'children',
    'style',
  ]);

  const columns = () => local.columns ?? 1;
  const columnsSm = () => local.columnsSm ?? 2;
  const columnsMd = () => local.columnsMd ?? 2;
  const columnsLg = () => local.columnsLg ?? 3;
  const columnsXl = () => local.columnsXl ?? 4;
  const gap = () => local.gap ?? 16;
  const columnFill = () => local.columnFill ?? 'balance';
  const height = () => local.height ?? 0;

  return (
    <div
      class={`exhuma-css-masonry w-full ${columnsSm() ? `sm:[column-count:${columnsSm()}] ` : ''}${columnsMd() ? `md:[column-count:${columnsMd()}] ` : ''}${columnsLg() ? `lg:[column-count:${columnsLg}] ` : ''}${columnsXl() ? `xl:[column-count:${columnsXl()}] ` : ''}${local.class ?? ''}`}
      style={{
        'column-count': columns(),
        'column-gap': `${gap()}px`,
        'column-fill': columnFill() === 'auto' ? 'auto' : 'balance',
        ...(columnFill() === 'auto' && height() > 0 ? { height: `${height()}px`, 'overflow-y': 'auto' } : {}),
        ...(typeof local.style === 'object' ? local.style : {}),
      }}
      {...others}
    >
      {local.children}
    </div>
  );
};

