export function initCssMasonry(selector = '[data-exhuma-css-masonry]', options = {}) {
  const elements = document.querySelectorAll(selector);

  elements.forEach((el) => {
    const cols = options.columns ?? el.dataset.columns ?? 1;
    const gap = options.gap ?? el.dataset.gap ?? 16;
    const fill = options.columnFill ?? el.dataset.columnFill ?? 'balance';
    const height = options.height ?? parseInt(el.dataset.height || '0', 10);

    el.style.columnCount = cols;
    el.style.columnGap = `${gap}px`;
    el.style.columnFill = fill === 'auto' ? 'auto' : 'balance';

    if (fill === 'auto' && height > 0) {
      el.style.height = `${height}px`;
      el.style.overflowY = 'auto';
    }

    Array.from(el.children).forEach((child) => {
      child.style.breakInside = 'avoid';
      child.style.marginBottom = `${gap}px`;
    });
  });
}

