class ExhumaCssMasonry extends HTMLElement {
  static get observedAttributes() {
    return ['columns', 'gap', 'column-fill', 'height'];
  }

  connectedCallback() {
    this.render();
  }

  attributeChangedCallback() {
    this.render();
  }

  render() {
    const cols = this.getAttribute('columns') || '1';
    const gap = this.getAttribute('gap') || '16';
    const fill = this.getAttribute('column-fill') || 'balance';
    const height = parseInt(this.getAttribute('height') || '0', 10);

    this.style.display = 'block';
    this.style.width = '100%';
    this.style.columnCount = cols;
    this.style.columnGap = `${gap}px`;
    this.style.columnFill = fill === 'auto' ? 'auto' : 'balance';

    if (fill === 'auto' && height > 0) {
      this.style.height = `${height}px`;
      this.style.overflowY = 'auto';
    }
  }
}

if (!customElements.get('exhuma-css-masonry')) {
  customElements.define('exhuma-css-masonry', ExhumaCssMasonry);
}

